-- Run this in the Supabase SQL editor.
-- Restores the original Korean demo addresses for the 8 seed members
-- (same values as 0005_seed_demo_members.sql).

update public.members
set address = case id
  when 'a0000000-0000-0000-0000-000000000001' then '서울시 강남구'
  when 'a0000000-0000-0000-0000-000000000002' then '서울시 서초구'
  when 'a0000000-0000-0000-0000-000000000003' then '서울시 송파구'
  when 'a0000000-0000-0000-0000-000000000004' then '경기도 성남시'
  when 'a0000000-0000-0000-0000-000000000005' then '경기도 용인시'
  when 'a0000000-0000-0000-0000-000000000006' then '서울시 마포구'
  when 'a0000000-0000-0000-0000-000000000007' then '인천시 남동구'
  when 'a0000000-0000-0000-0000-000000000008' then '서울시 영등포구'
end
where id in (
  'a0000000-0000-0000-0000-000000000001',
  'a0000000-0000-0000-0000-000000000002',
  'a0000000-0000-0000-0000-000000000003',
  'a0000000-0000-0000-0000-000000000004',
  'a0000000-0000-0000-0000-000000000005',
  'a0000000-0000-0000-0000-000000000006',
  'a0000000-0000-0000-0000-000000000007',
  'a0000000-0000-0000-0000-000000000008'
);
